import socket
import select
import queue
from datetime import datetime, timedelta

def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setblocking(False)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

    try:
        server_socket.bind((server_address, server_port))
        server_socket.listen(5)
        print(f"Echo server listening on {server_address}:{server_port}")

        inputs = [server_socket]
        outputs = []
        message_queues = {}
        start_time = datetime.now()
        run_until = start_time + timedelta(seconds=run_duration)

        status_message = f"Server started at {start_time.strftime('%Y-%m-%d %H:%M:%S')} and will run for {run_duration} seconds."

        while datetime.now() < run_until:
            readable, writable, exceptional = select.select(inputs, outputs, inputs, 1.0)

            for s in readable:
                if s is server_socket:
                    try:
                        client_socket, client_address = s.accept()
                        client_socket.setblocking(False)
                        inputs.append(client_socket)
                        message_queues[client_socket] = queue.Queue()
                        print(f"New connection from {client_address}")
                    except socket.error:
                        continue
                else:
                    try:
                        data = s.recv(buffer_size)
                        if data:
                            current_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S.%f')
                            response = f"{data.decode('utf-8').strip()} | Server time: {current_time}\n"
                            message_queues[s].put(response.encode('utf-8'))
                            if s not in outputs:
                                outputs.append(s)
                        else:
                            if s in outputs:
                                outputs.remove(s)
                            inputs.remove(s)
                            s.close()
                            del message_queues[s]
                    except socket.error:
                        if s in outputs:
                            outputs.remove(s)
                        inputs.remove(s)
                        s.close()
                        del message_queues[s]

            for s in writable:
                try:
                    if not message_queues[s].empty():
                        next_msg = message_queues[s].get_nowait()
                        s.send(next_msg)
                    else:
                        outputs.remove(s)
                except socket.error:
                    if s in outputs:
                        outputs.remove(s)
                    inputs.remove(s)
                    s.close()
                    del message_queues[s]

            for s in exceptional:
                inputs.remove(s)
                if s in outputs:
                    outputs.remove(s)
                s.close()
                if s in message_queues:
                    del message_queues[s]

        end_time = datetime.now()
        duration = (end_time - start_time).total_seconds()
        status_message = f"Server ran for {duration:.2f} seconds. Shutting down."

    except Exception as e:
        status_message = f"Server encountered an error: {str(e)}"
    finally:
        server_socket.close()

    return status_message
```

