def find_unique_element(nums):
    left, right = 0, len(nums) - 1

    while left < right:
        mid = (left + right) // 2

        # Check if mid is even or odd
        if mid % 2 == 1:
            mid -= 1  # Make mid even to ensure pairs

        # If the pair is not the same, the unique element is on the left
        if nums[mid] != nums[mid + 1]:
            right = mid
        else:
            left = mid + 2

    return nums[left]
