def solve_linear_diophantine(a, b, n):
    def extended_gcd(x, y):
        if x == 0:
            return y, 0, 1
        gcd, px, py = extended_gcd(y % x, x)
        x = py - (y // x) * px
        y = px
        return gcd, x, y

    gcd, x, y = extended_gcd(abs(a), abs(b))

    if n % gcd != 0:
        return None

    x *= n // gcd
    y *= n // gcd

    if a < 0:
        x = -x
    if b < 0:
        y = -y

    return (x, y)

