def max_bitonic_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # Initialize arrays to store maximum increasing and decreasing sums
    inc = [0] * n
    dec = [0] * n

    # Fill inc array: maximum sum ending at each index with increasing sequence
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # Fill dec array: maximum sum starting at each index with decreasing sequence
    for i in range(n-1, -1, -1):
        dec[i] = arr[i]
        for j in range(i+1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # Find maximum sum of bitonic subsequence
    max_sum = 0
    for i in range(n):
        max_sum = max(max_sum, inc[i] + dec[i] - arr[i])

    return max_sum
