def nth_newman_shanks_williams_prime(n):
    if n <= 0:
        return None

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def next_nsw_prime():
        a, b = 1, 1
        while True:
            a, b = b, 2 * b + a
            if is_prime(b):
