def find_median_of_two_sorted_lists(list1, list2):
    n = len(list1)
    left = 0
    right = n

    while left <= right:
        partition1 = (left + right) // 2
        partition2 = n - partition1

        max_left1 = float('-inf') if partition1 == 0 else list1[partition1 - 1]
        min_right1 = float('inf') if partition1 == n else list1[partition1]

        max_left2 = float('-inf') if partition2 == 0 else list2[partition2 - 1]
        min_right2 = float('inf') if partition2 == n else list2[partition2]

        if max_left1 <= min_right2 and max_left2 <= min_right1:
            if n % 2 == 1:
                return min(min_right1, min_right2)
            else:
                return (max(max_left1, max_left2) + min(min_right1, min_right2)) / 2
        elif max_left1 > min_right2:
            right = partition1 - 1
        else:
            left = partition1 + 1
