        try:
            if platform.system() == "Windows":
                result = subprocess.run(["wmic", "cpu", "get", "loadpercentage"], 
                                      capture_output=True, text=True, check=False)
                cpu_usage = result.stdout.strip().split('\n')
                cpu_usage = [line for line in cpu_usage if line.strip().isdigit()]
                if cpu_usage:
                    cpu_usage = int(cpu_usage[0])
                else:
                    cpu_usage = 0
            else:
                result = subprocess.run(["top", "-bn1"], capture_output=True, text=True, check=False)
                cpu_line = [line for line in result.stdout.split('\n') if 'Cpu(s)' in line]
                if cpu_line:
                    cpu_usage_str = cpu_line[0].split(',')[0].split()[1]
                    cpu_usage = float(cpu_usage_str.strip('%'))
                else:
                    cpu_usage = 0
        except Exception:
            cpu_usage = 0

        timestamp = time.time()
        log_data.append({"timestamp": timestamp, "cpu_usage": cpu_usage})

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(log_data, f, indent=2)
        return LOGFILE_PATH
    except IOError:
        return None
