    for url in urls:
        parsed_url = urllib.parse.urlparse(url)
        domains.add(parsed_url.netloc)

    # Dictionary to store geolocation data
    geolocation_data = {}

    # Fetch geolocation data for each domain
    for domain in domains:
        try:
            # Use IP API to get geolocation data
            response = requests.get(f"http://ip-api.com/json/{domain}?fields=status,country,region,city,zip,lat,lon,timezone,isp,org,as,query&key={API_KEY}")
            if response.status_code == 200:
                data = response.json()
                if data.get('status') == 'success':
                    geolocation_data[domain] = data
                else:
                    geolocation_data[domain] = None
            else:
                geolocation_data[domain] = None
        except Exception:
            geolocation_data[domain] = None

    return geolocation_data
