import numpy as np
from scipy import stats

# Constants
FEATURES = ['feature1', 'feature2', 'feature3', 'feature4', 'feature5']

def task_func(df, dct):
    try:
        if not isinstance(df, pd.DataFrame) or not isinstance(dct, dict):
            return "Invalid input"

        if not all(feature in df.columns for feature in FEATURES):
            return "Invalid input"

        # Replace values based on dictionary mapping
        df_modified = df.replace(dct)

        result = {}
        for feature in FEATURES:
            if feature not in df_modified.columns:
                result[feature] = {"mean": None, "median": None, "mode": None, "variance": None}
                continue

            values = df_modified[feature].dropna().values

            if len(values) == 0:
                result[feature] = {"mean": None, "median": None, "mode": None, "variance": None}
                continue

            mean_val = np.mean(values)
            median_val = np.median(values)
            mode_val = stats.mode(values, keepdims=True).mode[0]
            variance_val = np.var(values, ddof=1) if len(values) > 1 else 0

            result[feature] = {
                "mean": float(mean_val),
                "median": float(median_val),
                "mode": float(mode_val),
                "variance": float(variance_val)
            }

        return result

    except Exception:
        return "Invalid input"
