def task_func(points):
    if len(points) <= 1:
        return []

    # Convert single values to tuples with both coordinates equal
    processed_points = []
    for point in points:
        if isinstance(point, (int, float)):
            processed_points.append((point, point))
        else:
            processed_points.append(point)

    # Calculate Euclidean distances between consecutive points
    distances = []
    for i in range(len(processed_points) - 1):
        dist = distance.euclidean(processed_points[i], processed_points[i + 1])
        distances.append(dist)

