        else:
            raise KeyError(f"Key '{key}' not found in the path")

    if isinstance(current, list):
        values = []
        for item in current:
            if isinstance(item, (int, float)):
                values.append(item)
            elif isinstance(item, str):
                try:
                    num = float(item)
                    values.append(num)
                except ValueError:
                    continue
        if not values:
            raise ValueError("No numeric data found")
    else:
        raise ValueError("Data is not in a list format")

    fig, ax = plt.subplots()
    sns.boxplot(x=values, ax=ax)
    ax.set_title('Boxplot of Extracted Numerical Data')
    ax.set_xlabel('Values')

    return fig
